[CmdletBinding()]
param([string]$ProjectRoot)
$ErrorActionPreference='Stop';if([string]::IsNullOrWhiteSpace($ProjectRoot)){$ProjectRoot=(Get-Location).Path};$p=Join-Path $ProjectRoot 'ES/Automation/Contracts/es-ai-abc-engineering-competition-result-v1.schema.json';$s=Get-Content -Raw -Encoding UTF8 -LiteralPath $p|ConvertFrom-Json;$required=@($s.properties.evidenceSummary.required);$ok=(@('independentReplayVerifiedCount','providerScoreComparisonStatus')|ForEach-Object{$_ -in $required}) -notcontains $false;$pass=($s.additionalProperties -eq $false -and $ok -and $s.properties.evidenceSummary.additionalProperties -eq $false);$state='failed';if($pass){$state='passed'};[pscustomobject]@{status=$state;strictTopLevel=$s.additionalProperties -eq $false;independentReplayBound='independentReplayVerifiedCount' -in $required;providerStabilityBound='providerScoreComparisonStatus' -in $required};if(-not $pass){exit 1}
